// Keep these imports outside the page bundle so they read the external image
// registry rather than the options inlined into the page bundle.
const React = require('react')
const { getImageConfig } = require('next/dist/shared/lib/image-config-runtime')
const { getImageProps } = require('next/image')

exports.initialProps = getImageProps({
  src: '/assets/probe.png',
  alt: 'module-scope',
  fill: true,
})

function wrap(Image) {
  return function ExternalImage(props) {
    const config = getImageConfig()
    return React.createElement(Image, {
      ...props,
      'data-config-frozen':
        Object.isFrozen(config.deviceSizes) &&
        Object.isFrozen(config.qualities),
    })
  }
}

exports.ExternalImage = wrap(require('next/image').default)
exports.ExternalLegacyImage = wrap(require('next/legacy/image').default)
